def _ledger(data, sequence_first=False, original_tax=False):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            rank = (sequence, event.get("revision", 0), pos)
        else:
            rank = (event.get("revision", 0), pos)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), mode)
        base = raw if original_tax else net
        tax = _rounded(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best = None
    best_vector = None

    def search(required, assigned, edges):
        nonlocal best, best_vector
        # Intersect every accumulated constraint and reject conflicts early.
        for name, bounds in required.items():
            if bounds[0] > bounds[1]:
                return
            if name in assigned and not (bounds[0] <= assigned[name]["version"] <= bounds[1]):
                return
        todo = [name for name in required if name not in assigned]
        if not todo:
            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in assigned):
                return
            vector = tuple(assigned[n]["version"] if n in assigned else -1 for n in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {n: assigned[n]["version"] for n in assigned}
            return

        name = min(todo)
        low, high = required[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in sorted(rows, key=lambda r: r["version"], reverse=True):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_required = dict(required)
            next_edges = {key: list(value) for key, value in edges.items()}
            active_deps = [d for d in row.get("deps", [])
                           if not d.get("feature") or d.get("feature") in features]
            next_edges[name] = [d["name"] for d in active_deps]
            valid = True
            for dep in active_deps:
                dep_name = dep["name"]
                dep_low, dep_high = dep["min"], dep["max"]
                if dep_name in next_required:
                    old_low, old_high = next_required[dep_name]
                    dep_low, dep_high = max(dep_low, old_low), min(dep_high, old_high)
                next_required[dep_name] = (dep_low, dep_high)
                if dep_low > dep_high:
                    valid = False
                    break
                if dep_name in next_assigned and not (dep_low <= next_assigned[dep_name]["version"] <= dep_high):
                    valid = False
                    break
            if valid:
                search(next_required, next_assigned, next_edges)

    roots = {name: (bounds[0], bounds[1]) for name, bounds in data["roots"].items()}
    search(roots, {}, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    n = len(jobs)
    for mask in range(1 << n):
        chosen = [jobs[i] for i in range(n) if mask & (1 << i)]
        if len(chosen) != k:
            continue
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in quotas.items()):
            continue
        events = []
        for job in chosen:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        # End events precede starts at equal times for half-open intervals.
        events.sort(key=lambda item: (item[0], item[1]))
        concurrent = 0
        valid = True
        for _, change in events:
            concurrent += change
            if concurrent > 2:
                valid = False
                break
        if not valid:
            continue
        ordered_ids = sorted(ids)
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value
                or (value == best_value and ordered_ids < best_ids)):
            best_value, best_ids = value, ordered_ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    start = data["start"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bit_for.get(dest, 0)
                next_state = (dest, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, left))
    return {"arrival": None}


